CREATE OR REPLACE FUNCTION public.admin_export_orders(p_view text, p_query text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_category text DEFAULT NULL::text, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_min_cents integer DEFAULT NULL::integer, p_max_cents integer DEFAULT NULL::integer, p_after_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_after_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 500)
 RETURNS TABLE(id uuid, sort_at timestamp with time zone, created_at timestamp with time zone, status text, total_cents integer, refunded_cents integer, currency text, transferred boolean, disputed_at timestamp with time zone, dispute_resolved_at timestamp with time zone, dispute_category text, dispute_reason text, refund_offer_cents integer, buyer_id uuid, buyer_username text, buyer_display_name text, seller_id uuid, seller_username text, seller_display_name text, title text)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
#variable_conflict use_column
declare
  v_q text := nullif(trim(coalesce(p_query, '')), '');
  v_hex text;
  v_like text;
  v_limit int := least(greatest(coalesce(p_limit, 500), 1), 1000);
begin
  if p_view not in ('orders', 'disputes_open', 'disputes_resolved') then
    raise exception 'Unknown export view %', p_view using errcode = '22023';
  end if;
  if (p_after_at is null) <> (p_after_id is null) then
    raise exception 'A page cursor needs both its time and its id' using errcode = '22023';
  end if;
  -- An id-shaped search is an order-id prefix (dashes optional); a pi_
  -- search is a payment reference; anything else is a name (or, for
  -- disputes, an item title).
  if v_q ~* '^[0-9a-f-]{8,}$' then v_hex := replace(lower(v_q), '-', ''); end if;
  -- Literal text inside an ILIKE pattern: \ % and _ match themselves.
  v_like := '%' || replace(replace(replace(coalesce(v_q, ''), '\', '\\'), '%', '\%'), '_', '\_') || '%';

  return query
  with picked as (
    select o.*,
      case p_view
        when 'orders' then o.created_at
        -- An open dispute missing its timestamp still gets a place in the order.
        when 'disputes_open' then coalesce(o.disputed_at, o.created_at)
        else o.dispute_resolved_at
